     "h": "The home of gongfu tea",
     "p": "Gongfu tea (工夫茶) developed in Chaozhou, Guangdong, and the Minnan region of southern Fujian. Records from the Qing dynasty already describe Chaozhou gongfu tea, and the style has strongly influenced tea practice across China and Taiwan."
