     "h": "The samovar: a kettle that boils itself",
     "p": "A samovar is a metal vessel that boils water and keeps it hot; its very name carries the Russian sense of \"self-boiling.\" Traditionally it was fired with wood or charcoal; today electric versions are common. With a samovar at the centre of the table, family and guests would gather around it and spend long hours over tea."
