    {
     "h": "Zavarka: strong concentrate, diluted",
     "p": "The Russian method starts with zavarka — tea leaves brewed very strong in a small pot into a concentrate. To serve, you pour a little zavarka into a cup and top it up with hot water from the samovar, adjusting the strength to your own taste. Brew once, and many people can enjoy tea for hours, each at their preferred strength."
    },
    {
     "h": "Jam, and sugar between the teeth",
     "p": "Russians traditionally take a spoonful of jam (varenye) alongside their tea, or stir it in. An older custom was to hold a sugar cube between the teeth and sip the tea through it, letting the sweetness seep in little by little. Bitter and sweet enjoyed together, in small doses — a tea culture shaped by a cold country."
    },
    {
     "h": "The samovar on the rails",
     "p": "In a country as vast as Russia, long-distance trains were part of life, and tea was their companion. On trains, tea was served in glasses set in metal holders called podstakannik, so the drink would not spill as the carriage rocked — an image that became iconic. Even today, a hot glass of tea comforts passengers on Russia's long rail journeys."
    }
