     "h": "Pouring — the gap in the lid is the key",
     "p": "Tilt the lid slightly so a small gap opens for the tea to flow through. Hold the rim of the bowl between your thumb and middle finger, and press the top of the lid gently with your index finger to keep it in place. Tip your wrist and only the liquid pours out, while the lid holds the leaves back. If the gap is too wide the leaves escape too, so keep it narrow at first."
