     "p": "If the gaiwan is too hot to hold, you have usually filled it too full. Fill only to about eight-tenths, and if it is still hot, lift and move it by the saucer instead. A gaiwan whose rim flares slightly outward stays cooler where your fingers touch, which makes it a friendly choice for beginners."
