     "p": "Green teas and delicate oolongs keep their freshness longer in the fridge, as long as the seal is truly airtight. But if you open cold tea right away, moisture from the air condenses on the leaves, so let the container return to room temperature before opening it. Once opened, avoid moving tea back and forth between fridge and shelf — keep it cool and finish it reasonably soon."
